<script>
(()=>{const inputs=[...document.querySelectorAll('.usd-asset-input')],usd=document.getElementById('portfolioUsdPreview'),ngn=document.getElementById('portfolioNgnPreview'),source=document.getElementById('withdrawSource'),hint=document.getElementById('quickWithdrawHint'),form=document.getElementById('usdNgnForm');if(!usd||!ngn)return;const rate={{ json_encode((float)$sellRate) }},minimumNgn={{ json_encode((float)$minimumWithdrawalNgn) }};const fUsd=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}),fNgn=new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2});function update(){let total=0;inputs.forEach(input=>{const amount=Math.min(Math.max(Number(input.value)||0,0),Number(input.dataset.balance)||0);total+=amount*(Number(input.dataset.price)||0)});usd.textContent=fUsd.format(total);ngn.textContent=fNgn.format(total*rate)}function chooseMode(mode){document.querySelectorAll('.usd-mode').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(!source?.value){hint.textContent='Choose an available crypto balance first.';source?.focus();return}const input=inputs.find(i=>i.dataset.coin===source.value),option=source.selectedOptions[0];if(!input||!option)return;inputs.forEach(i=>{if(i!==input)i.value=''});const balance=Number(option.dataset.balance),price=Number(option.dataset.price);if(mode==='max'){input.value=balance.toFixed(8);hint.textContent='Maximum selected: your full available '+source.value+' balance.'}else if(mode==='min'){const minCoin=Math.ceil((minimumNgn/rate/price)*1e8)/1e8;if(minCoin>balance){input.value='';hint.textContent='Your '+source.value+' balance is below the minimum withdrawal value.'}else{input.value=minCoin.toFixed(8);hint.textContent='Minimum selected: approximately '+fNgn.format(minCoin*price*rate)+' credited to your Naira wallet.'}}else{input.value='';input.focus();hint.textContent='Enter a custom '+source.value+' amount in its wallet row below.'}update()}document.querySelectorAll('.usd-mode').forEach(b=>b.addEventListener('click',()=>chooseMode(b.dataset.mode)));source?.addEventListener('change',()=>{document.querySelectorAll('.usd-mode').forEach(b=>b.classList.remove('active'));hint.textContent=source.value?'Select minimum, custom, or maximum.':'Choose an available crypto balance.'});inputs.forEach(input=>input.addEventListener('input',()=>{document.querySelectorAll('.usd-mode').forEach(b=>b.classList.remove('active'));update()}));form?.addEventListener('submit',event=>{update();if(!confirm('Convert '+usd.textContent+' of selected crypto and credit an estimated '+ngn.textContent+' to your Naira wallet? The final amount uses the current platform sell rate.'))event.preventDefault()});update();if(new URLSearchParams(location.search).has('withdraw'))document.getElementById('usd-naira-withdraw')?.scrollIntoView({behavior:'smooth',block:'center'});})();
</script>
